pm.test("Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Response contains a list of rooms", function () {
    const response = pm.response.json();
    pm.expect(response.rooms).to.be.an("array");
});


const rooms = pm.response.json().rooms;

pm.test("Every room has a valid ID", function () {
    rooms.forEach(room => {
        pm.expect(room.roomid).to.be.a("number");
        pm.expect(room.roomid).to.be.above(0);
    });
});

pm.test("Every room has a name", function () {
    rooms.forEach(room => {
        pm.expect(room.roomName).to.be.a("string").and.not.empty;
    });
});

pm.test("Every room has a valid price", function () {
    rooms.forEach(room => {
        pm.expect(room.roomPrice).to.be.a("number");
        pm.expect(room.roomPrice).to.be.at.least(0);
    });
});

pm.test("Existing room returns 200 OK", function () {
    pm.response.to.have.status(200);
});
